before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <array>
#include <iostream>
#include <span>
void setFirst(std::span<int> values) {
    if (!values.empty()) values[0] = 9;
}
int main() {
    std::array<int, 3> scores{1, 2, 3};
    setFirst(scores);
    std::cout << scores[0] << " " << scores.size() << "\n";
}
```

